CUSTOMER_CONTEXT_TOOL = {
    "name": "crm_get_customer_context",
    "description": (
        "Finds one customer by name or email and returns their profile, "
        "last 20 transactions and open support notes in a single call. Use "
        "it before answering any question about a specific customer's "
        "billing or history. If several customers match, it returns up to "
        "5 candidates instead, so ask the user which one they mean. Set "
        "response_format to 'detailed' only when a next step needs IDs."
    ),
    "input_schema": {
        "type": "object",
        "properties": {
            "customer": {"type": "string",
                         "description": "Full name or email address"},
            "response_format": {"type": "string",
                                "enum": ["concise", "detailed"]},
        },
        "required": ["customer"],
    },
}
